{"p":1,"verse":"103:1","says":"Baştaki 've' yemin edatıdır, yeminin cevabı ikinci ayete bırakılır; tek kelimelik birinci ayet bir eşiktir.","status":"written","blocks":["b01","b02"],"questions":["103:1/q03","103:1/q11","103:1/q22"]}
{"p":1,"verse":"103:2","says":"Hüküm ikinci ayette gelir; asrın ne olduğunu duymak kaybın nasıl bir kayıp olduğunu duymanın yoludur.","status":"written","blocks":["b03"],"questions":["103:2/q01","103:2/q10"]}
{"p":2,"verse":"103:1","says":"Asr nitelemesiz gelir; kelime hem günün bir dilimini hem zamanın bütününü adlandırır, belirlilik takısı hangisinin kastedildiğini söylemez; Kur'an başka surelerde de gün vakitlerine yemin eder.","status":"written","blocks":["b04","b05","b06"],"questions":["103:1/q01","103:1/q02","103:1/q09"]}
