{"p":1,"verse":"103:1","says":"Baştaki 've' yemin edatıdır, yeminin cevabı ikinci ayete bırakılır; tek kelimelik birinci ayet bir eşiktir.","status":"written","blocks":["b01","b02"],"questions":["103:1/q03","103:1/q11","103:1/q22"]}
{"p":1,"verse":"103:2","says":"Hüküm ikinci ayette gelir; asrın ne olduğunu duymak kaybın nasıl bir kayıp olduğunu duymanın yoludur.","status":"written","blocks":["b03"],"questions":["103:2/q01","103:2/q10"]}
{"p":2,"verse":"103:1","says":"Asr nitelemesiz gelir; kelime hem günün bir dilimini hem zamanın bütününü adlandırır, belirlilik takısı hangisinin kastedildiğini söylemez; Kur'an başka surelerde de gün vakitlerine yemin eder.","status":"written","blocks":["b04","b05","b06"],"questions":["103:1/q01","103:1/q02","103:1/q09"]}
{"p":2,"verse":"74:34","says":"Ağardığında sabaha yemin, vakti bir hareketle anar.","status":"agreed","blocks":["b10"],"questions":["74:34/q03"]}
{"p":2,"verse":"89:1","says":"Şafağa yemin, Kur'an'ın gün vakitlerine yeminlerinden biridir.","status":"written","blocks":["b07"],"questions":["89:1/q03"]}
{"p":2,"verse":"92:1","says":"Her şeyi örttüğünde geceye yemin, vakti bir hareketle anar.","status":"written","blocks":["b09"],"questions":["92:1/q04"]}
{"p":2,"verse":"93:1","says":"Kuşluk vaktine yemin, gün vakitlerine yeminlerden biridir.","status":"written","blocks":["b08"],"questions":["93:1/q01","103:1/q09"]}
{"p":3,"verse":"103:1","says":"Türkçe kelimeyi ikiye bölmüştür: asır yüz yıl, ikindi günün sonu; ayetteki kelime saati de çağı da bir arada tutar.","status":"same_as","blocks":["b05"],"questions":["103:1/q02"]}
{"p":4,"verse":"103:1","says":"Araplar günün iki ucunu 'iki asr' diye anardı; ayetin akşamüstü anlamı bu kenarlardan biridir.","status":"same_as","blocks":["b04"],"questions":["103:1/q01"]}
{"p":4,"verse":"6:52","says":"Sabah akşam Rablerine yalvaranlar: günün iki kenarı Kur'an'ın kendi sözleriyle anılır.","status":"written","blocks":["b11"],"questions":["6:52/q05","6:52/q04"]}
{"p":4,"verse":"11:114","says":"Namazın vakti gündüzün iki ucuyla verilir; asrın akşamüstü anlamı bu uçlardan biridir.","status":"written","blocks":["b12"],"questions":["11:114/q02","103:1/q01"]}
{"p":5,"verse":"103:1","says":"Asr gecikmeyi, uzun çağı, anı ve ömrün evrelerini taşır; akşamüstü günün kalanının en az olduğu, iş için vaktin daraldığı saattir.","status":"written","blocks":["b13"],"questions":["103:1/q04","103:1/q01"]}
{"p":6,"verse":"103:1","says":"İkinci ayetin kaybı ve üçüncü ayetin iman ve salih işi verilmiş süre içinde yer alır.","status":"same_as","blocks":["b13"],"questions":["103:1/q04"]}
{"p":6,"verse":"35:37","says":"Cevap ömrü, düşünecek olanın düşünebileceği kadar verilmiş bir süre olarak anar.","status":"agreed","blocks":["b15"],"questions":["35:37/q11"]}
