{"p":8,"verse":"103:1","says":"Sıkmanın ürünü hayrın ve bağışın adı olur; sıkma göğe, yağmurla sıkılan buluta taşınır.","status":"same_as","blocks":["b05"],"questions":["103:1/q02"]}
